import React, { useState, useEffect, useContext } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { AuthContext } from '../context/AuthContext';
import { API_URL } from '../config';
import { countries } from '../data/countries';

const Profile = () => {
  const { token, loading, user } = useContext(AuthContext);
  const navigate = useNavigate();

  const [formData, setFormData] = useState({ firstName: '', lastName: '', country: '', phone: '' });
  const [profileMsg, setProfileMsg] = useState('');

  const [enrollments, setEnrollments] = useState([]);
  const [loadingEnrollments, setLoadingEnrollments] = useState(true);

  const [pwPhase, setPwPhase] = useState('idle'); // idle | code-sent
  const [devCode, setDevCode] = useState('');
  const [codeInput, setCodeInput] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordMsg, setPasswordMsg] = useState('');

  useEffect(() => { if (!loading && !token) navigate('/login'); }, [token, loading]);

  useEffect(() => {
    if (!token) return;
    fetch(`${API_URL}/auth/me`, { headers: { Authorization: `Bearer ${token}` } })
      .then(res => res.json())
      .then(data => setFormData({ firstName: data.first_name || '', lastName: data.last_name || '', country: data.country || '', phone: data.phone || '' }));

    fetch(`${API_URL}/auth/me/enrollments`, { headers: { Authorization: `Bearer ${token}` } })
      .then(res => res.ok ? res.json() : [])
      .then(setEnrollments)
      .finally(() => setLoadingEnrollments(false));
  }, [token]);

  const handleNameChange = (e) => { const { name, value } = e.target; setFormData({ ...formData, [name]: value.replace(/[^a-zA-ZÀ-ÿ\s\-]/g, '') }); };
  const handlePhoneChange = (e) => { setFormData({ ...formData, phone: e.target.value.replace(/[^0-9+\s]/g, '') }); };

  const saveProfile = async (e) => {
    e.preventDefault();
    setProfileMsg('');
    try {
      const res = await fetch(`${API_URL}/auth/me`, {
        method: 'PUT', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ first_name: formData.firstName, last_name: formData.lastName, country: formData.country, phone: formData.phone }),
      });
      if (!res.ok) throw new Error('Erreur lors de la mise à jour.');
      setProfileMsg('✓ Profil mis à jour.');
      setTimeout(() => setProfileMsg(''), 3000);
    } catch (err) { setProfileMsg(err.message); }
  };

  const requestCode = async () => {
    setPasswordMsg('');
    try {
      const res = await fetch(`${API_URL}/auth/request-password-change-code`, {
        method: 'POST', headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      setDevCode(data.code); // simulation — visible ici en attendant l'envoi par email réel
      setPwPhase('code-sent');
    } catch {
      setPasswordMsg('Erreur lors de la génération du code.');
    }
  };

  const confirmChange = async (e) => {
    e.preventDefault();
    setPasswordMsg('');
    if (newPassword !== confirmPassword) { setPasswordMsg('Les mots de passe ne correspondent pas.'); return; }
    try {
      const res = await fetch(`${API_URL}/auth/confirm-password-change`, {
        method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ code: codeInput, new_password: newPassword }),
      });
      if (!res.ok) { const data = await res.json().catch(() => ({})); throw new Error(data.detail || 'Erreur.'); }
      setPasswordMsg('✓ Mot de passe modifié.');
      setPwPhase('idle');
      setCodeInput(''); setNewPassword(''); setConfirmPassword(''); setDevCode('');
      setTimeout(() => setPasswordMsg(''), 3000);
    } catch (err) { setPasswordMsg(err.message); }
  };

  const formatDate = (isoString) => {
    if (!isoString) return '—';
    return new Date(isoString).toLocaleDateString('fr-FR', { day: '2-digit', month: 'long', year: 'numeric' });
  };

  if (loading || !token) return <div className="min-h-screen flex items-center justify-center text-slate-500 text-sm">Chargement...</div>;

  return (
    <div className="min-h-screen text-white">
      <Navbar />
      <div className="max-w-2xl mx-auto px-6 py-16 space-y-10">
        <div>
          <h1 className="text-2xl font-bold mb-1">Mon profil</h1>
          <p className="text-slate-500 text-sm">{user?.email}</p>
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6 space-y-4">
          <h3 className="text-sm font-bold text-white">Informations personnelles</h3>
          {profileMsg && <div className={`text-sm rounded-lg px-4 py-3 ${profileMsg.startsWith('✓') ? 'bg-emerald-500/10 border border-emerald-500/30 text-emerald-400' : 'bg-red-500/10 border border-red-500/30 text-red-400'}`}>{profileMsg}</div>}
          <form onSubmit={saveProfile} className="space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <input name="firstName" type="text" placeholder="Prénom" value={formData.firstName} onChange={handleNameChange} className="bg-slate-950 border border-slate-800 text-white px-4 py-3 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors" />
              <input name="lastName" type="text" placeholder="Nom" value={formData.lastName} onChange={handleNameChange} className="bg-slate-950 border border-slate-800 text-white px-4 py-3 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors" />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <select value={formData.country} onChange={(e) => setFormData({ ...formData, country: e.target.value })} className="bg-slate-950 border border-slate-800 text-white px-4 py-3 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors">
                <option value="">Pays</option>
                {countries.map(c => <option key={c.name} value={c.name}>{c.name} ({c.code})</option>)}
              </select>
              <input type="tel" placeholder="Téléphone" value={formData.phone} onChange={handlePhoneChange} className="bg-slate-950 border border-slate-800 text-white px-4 py-3 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors" />
            </div>
            <button type="submit" className="bg-blue-600 hover:bg-blue-500 text-white font-semibold px-6 py-3 rounded-lg text-sm transition-colors">Enregistrer</button>
          </form>
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6 space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-bold text-white">Mes formations</h3>
            <span className="text-xs text-slate-500">{enrollments.length} cours achetés</span>
          </div>

          {loadingEnrollments ? (
            <p className="text-slate-500 text-sm">Chargement...</p>
          ) : enrollments.length === 0 ? (
            <div className="text-center py-8">
              <p className="text-slate-500 text-sm mb-3">Aucune formation pour l'instant.</p>
              <Link to="/catalog" className="text-blue-400 hover:text-blue-300 font-semibold text-sm">Découvrir le catalogue →</Link>
            </div>
          ) : (
            <div className="space-y-3">
              {enrollments.map(e => {
                const percent = e.total_lessons > 0 ? Math.round((e.completed_lessons / e.total_lessons) * 100) : 0;
                return (
                  <div key={e.course_id} className="bg-slate-950 border border-slate-800 rounded-lg p-4">
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-sm font-semibold text-white">{e.course_title}</span>
                      <span className="text-[11px] text-slate-500 uppercase font-semibold">{e.payment_method || 'Gratuit'}</span>
                    </div>
                    <div className="w-full bg-slate-800 h-1.5 rounded-full overflow-hidden mb-2">
                      <div className="h-full bg-gradient-to-r from-blue-600 to-cyan-500 rounded-full" style={{ width: `${percent}%` }}></div>
                    </div>
                    <div className="flex items-center justify-between text-xs text-slate-500">
                      <span>{e.completed_lessons} / {e.total_lessons} leçons regardées — {percent}%</span>
                      <span>Acheté le {formatDate(e.purchased_at)}</span>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6 space-y-4">
          <h3 className="text-sm font-bold text-white">Changer le mot de passe</h3>
          {passwordMsg && <div className={`text-sm rounded-lg px-4 py-3 ${passwordMsg.startsWith('✓') ? 'bg-emerald-500/10 border border-emerald-500/30 text-emerald-400' : 'bg-red-500/10 border border-red-500/30 text-red-400'}`}>{passwordMsg}</div>}

          {pwPhase === 'idle' ? (
            <button onClick={requestCode} className="bg-blue-600 hover:bg-blue-500 text-white font-semibold px-6 py-3 rounded-lg text-sm transition-colors">
              Recevoir un code pour changer le mot de passe
            </button>
          ) : (
            <>
              <div className="bg-amber-500/10 border border-amber-500/30 text-amber-400 text-xs rounded-lg px-4 py-3">
                Simulation : en attendant la configuration email, ton code est affiché ici directement → <span className="font-bold text-sm">{devCode}</span>
              </div>
              <form onSubmit={confirmChange} className="space-y-3">
                <input type="text" maxLength={6} placeholder="Code à 6 chiffres" value={codeInput} onChange={(e) => setCodeInput(e.target.value.replace(/\D/g, ''))} className="w-full bg-slate-950 border border-slate-800 text-white text-center text-xl tracking-[0.4em] px-4 py-3 rounded-lg outline-none focus:border-blue-500 transition-colors" />
                <input type="password" placeholder="Nouveau mot de passe" required value={newPassword} onChange={(e) => setNewPassword(e.target.value)} className="w-full bg-slate-950 border border-slate-800 text-white px-4 py-3 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors" />
                <input type="password" placeholder="Confirmer le nouveau mot de passe" required value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} className="w-full bg-slate-950 border border-slate-800 text-white px-4 py-3 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors" />
                <button type="submit" className="bg-blue-600 hover:bg-blue-500 text-white font-semibold px-6 py-3 rounded-lg text-sm transition-colors">Confirmer le changement</button>
              </form>
            </>
          )}
        </div>
      </div>
    </div>
  );
};
export default Profile;
